[
  {
    "id": "spider-hat-visitor",
    "prompt": "Edit only the spider's body anatomy: merge the separate round head and middle thorax into ONE continuous cephalothorax, keeping the large abdomen as its second body segment. There must be TWO main body masses total, not three. Preserve exactly EIGHT legs, four on either side, their poses, eyes, smile, gray colors, purple hat and transparent background. Keep clean polished artwork. No new elements, no extra limbs, no halo.",
    "source": "[workspace]/work/production/wave_153/source/spider-hat-visitor-v2.png"
  },
  {
    "id": "spider-lantern-visitor",
    "prompt": "Edit this clipart with two corrections. First remove ALL background glow and colored haze, leaving genuine transparent background and all gaps transparent. Second the spider currently has NINE long walking legs: remove the extra shortest inward front leg whose pointed tip sits immediately under the LEFT eye toward the center-bottom, at about x970 y825 of this1536x1024image. Keep the other eight legs: four extending to viewer-left and four to viewer-right. Preserve body, smiling face, orange lantern and all other lines and colors. No added legs or arms. Clean alpha edges and no shadow or glow outside the silhouettes.",
    "source": "[workspace]/work/production/wave_153/source/spider-lantern-visitor-v2.png"
  }
]

[
  {
    "id": "spider-stem-balancer",
    "source": "[workspace]/work/production/wave_153/source/spider-stem-balancer.png",
    "prompt": "Edit this spider balanced on a pumpkin stem clipart. Preserve all EIGHT legs, four per side, two body parts and face. Complete the pumpkin so its entire round lower half is visible rather than a straight cut crop. Show a whole small squat pumpkin under the curled stem, fit whole composition within central70% canvas with clear margins. Refine dense microtexture to smooth professional layered cel shading and broad designed fur shapes. Crisp ink contours, rich colors. True transparent background, no fringe, text or shadow."
  },
  {
    "id": "spider-hat-visitor",
    "source": null,
    "prompt": "One original polished cartoon spider clipart for a Halloween card: smooth charcoal spider stands above a small deep purple pointed costume hat. Face angled slightly toward the hat below, overhead view. Show EXACTLY EIGHT curved segmented walking legs in FOUR PAIRS, four left and four right, every attachment and tip separate. Two main body segments. Four legs fan out left at11,10,8,7 oclock; four fan out right at1,2,4,5 oclock. Do not hide any leg behind body or hat. No antennae, pedipalps or extra arms. A lovely expressive face, confident ink lines, clean flat rich color areas with sophisticated smooth cel shading, broad stylized fur edges only. No individual fur hairs or noise. Art central70% of square, genuinely transparent background and holes, clean edges, no labels or words."
  },
  {
    "id": "spider-lantern-visitor",
    "source": null,
    "prompt": "One original polished spider storybook clipart for nighttime stories: a russet spider next to a compact orange metal lantern with flat golden panes, lantern on left with a gap and spider on right. Slight overhead view. EIGHT clearly countable legs, FOUR left and FOUR right, arranged in four symmetrical jointed pairs around TWO body segments. All eight tips visible and unobscured by lantern, no extra arms, pedipalps or antennae. Expressive gentle face, elegant hand-inked outlines. Broad smooth rich color areas and carefully composed cel shading, no microscopic texture or fine hairs. Whole art in central70% of canvas with generous empty margin. True transparent background and gaps, no emitted light or glow, no halo, no white fringe, no text."
  }
]
